// Reference solution
function toHex(bytes) {
  // Each byte ⇒ exactly two lower-case hex digits (10 ⇒ "0a", never "a"), joined by one space.
  return bytes.map(function (b) { return (b < 16 ? '0' : '') + b.toString(16); }).join(' ');
}

